<?php $gl=db()->query('SELECT * FROM gl_accounts')->fetchAll(); $cc=db()->query('SELECT * FROM cost_centers')->fetchAll(); ?>
<div class="row g-3"><div class="col-md-6"><div class="card p-3"><h5>GL Accounts</h5><table class="table table-sm"><tr><th>GL</th><th>Name</th></tr><?php foreach($gl as $r):?><tr><td><?=e($r['gl_code'])?></td><td><?=e($r['gl_name'])?></td></tr><?php endforeach;?></table></div></div><div class="col-md-6"><div class="card p-3"><h5>Cost Centers</h5><table class="table table-sm"><tr><th>Center</th><th>Name</th></tr><?php foreach($cc as $r):?><tr><td><?=e($r['cost_center_code'])?></td><td><?=e($r['cost_center_name'])?></td></tr><?php endforeach;?></table></div></div></div>
